def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    op = [h[1] for h in history]
    my = [h[0] for h in history]
    last_op = op[-1]
    last_my = my[-1]

    # Count consecutive opponent defections at the tail
    tail_def = 0
    for a in reversed(op):
        if a == 'D':
            tail_def += 1
        else:
            break

    # Count consecutive opponent cooperations at the tail
    tail_coop = 0
    for a in reversed(op):
        if a == 'C':
            tail_coop += 1
        else:
            break

    total_op_def = op.count('D')
    total_op_coop = n - total_op_def

    window = min(12, n)
    recent = op[-window:]
    recent_coop = recent.count('C')
    recent_rate = recent_coop / window
    overall_rate = total_op_coop / n

    remaining = 100 - n

    # Endgame: squeeze the last rounds
    if remaining <= 1:
        return 'D'
    if remaining <= 3 and overall_rate >= 0.6:
        if rng.random() < 0.6:
            return 'D'
        return 'C'

    # Very cooperative opponent: probe and exploit late
    if total_op_def <= 1 and n >= 6:
        if remaining <= 8:
            if rng.random() < 0.6:
                return 'D'
            return 'C'
        # occasional probe
        if n % 7 == 0:
            return 'D'
        return 'C'

    # Highly cooperative opponent
    if overall_rate >= 0.85 and tail_def == 0:
        if n >= 20 and rng.random() < 0.08:
            return 'D'
        return 'C'

    # Opponent currently defecting persistently
    if tail_def >= 3:
        return 'D'

    # Opponent defected last round
    if last_op == 'D':
        # If opponent normally cooperative, forgive isolated defection once
        if tail_def == 1 and overall_rate >= 0.65 and remaining > 4:
            if rng.random() < 0.55:
                return 'C'
        return 'D'

    # Opponent cooperated last round
    if last_op == 'C':
        # I defected and they forgave: exploit a bit more if profitable
        if last_my == 'D':
            if overall_rate >= 0.5 and remaining > 3 and rng.random() < 0.45:
                return 'D'
            return 'C'

        # Opponent is mostly defective but just cooperated: cautious
        if overall_rate < 0.35:
            if rng.random() < 0.5:
                return 'D'
            return 'C'

        # Mildly defective opponent
        if recent_rate < 0.45:
            if rng.random() < 0.35:
                return 'D'
            return 'C'

        # Detect opponent shift toward defection
        if n >= 16:
            early = op[:n//2]
            late = op[n//2:]
            early_rate = early.count('C') / max(1, len(early))
            late_rate = late.count('C') / max(1, len(late))
            if early_rate - late_rate > 0.2:
                if rng.random() < 0.5:
                    return 'D'
                return 'C'

        # Exploit long cooperation streaks occasionally
        if tail_coop >= 5 and overall_rate >= 0.6:
            if rng.random() < 0.12:
                return 'D'
            return 'C'

        return 'C'

    return 'C'
